{
  "name": "pi-scripts",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "scripts": {
    "test": "vitest run --config vitest.config.ts",
    "test:watch": "vitest --config vitest.config.ts",
    "lint": "tsc --noEmit --project tsconfig.scripts.json",
    "script": "tsx scripts/"
  },
  "devDependencies": {
    "@playwright/test": "^1.60.0",
    "@types/better-sqlite3": "^7.6.13",
    "@types/node": "^22.15.3",
    "ts-morph": "^25.0.1",
    "typescript": "^5.8.3",
    "vitest": "^3.1.1"
  }
}
import { defineConfig } from 'vitest/config'

export default defineConfig({
  test: {
    globals: true,
    include: ['scripts/**/*.test.ts', 'shared/**/*.test.ts'],
    environment: 'node',
    pool: 'threads',
    poolOptions: {
      threads: {
        singleThread: true
      }
    },
    coverage: {
      provider: 'v8',
      reporter: ['text', 'lcov']
    }
  }
})

